n = int(input())

for _ in range(n):
    expr = input()
    try:
        # 1) split the text into tokens
        tokens = []
        number = ""
        for ch in expr:
            if ch.isdigit() or ch == ".":
                number += ch
                continue
            if number:
                tokens.append(number)
                number = ""
            if ch in "+-*/":
                tokens.append(ch)
            elif ch != " ":
                raise SyntaxError("INVALID_EXPRESSION")
        if number:
            tokens.append(number)

        # 2) check the pattern: number op number op ... number
        if len(tokens) % 2 == 0:
            raise SyntaxError("INVALID_EXPRESSION")
        values = []
        for i, tok in enumerate(tokens):
            if i % 2 == 0:
                try:
                    values.append(float(tok))
                except ValueError:      # an operator here, or something like "1.2.3"
                    raise SyntaxError("INVALID_EXPRESSION")
            elif tok not in "+-*/":
                raise SyntaxError("INVALID_EXPRESSION")

        # 3) evaluate: * and / first, then + and -
        terms = [values[0]]
        for i in range(1, len(values)):
            op = tokens[2 * i - 1]
            value = values[i]
            if op == "*":
                terms[-1] *= value
            elif op == "/":
                if value == 0:
                    raise ZeroDivisionError("DIVISION_BY_ZERO")
                terms[-1] /= value
            elif op == "+":
                terms.append(value)
            else:
                terms.append(-value)
        print(sum(terms))
    except (SyntaxError, ZeroDivisionError) as e:
        print(f"{type(e).__name__}: {e}")

tries, fails = map(int, input().split())

try:
    if tries < 1:
        raise ValueError("tries must be at least 1")

    succeeded = False
    for n in range(1, tries + 1):
        try:
            if n <= fails:
                raise ConnectionError(f"attempt {n} failed")
        except ConnectionError as err:
            print(err)              # report it and try again
            continue
        print(f"SUCCESS on attempt {n}")
        succeeded = True
        break

    if not succeeded:
        raise RuntimeError(f"FAILED after {tries} attempts")
except (ValueError, RuntimeError) as e:
    print(f"{type(e).__name__}: {e}")

