for _ in range(n):
    key = input()
    try:
        try:
            value = record[key]
        except KeyError as err:
            raise LookupError(f"missing field: {key}") from err
        if value is None:
            raise ValueError(f"empty field: {key}")
        print(f"{key}: {value}")
    except (LookupError, ValueError) as e:
        line = f"{type(e).__name__}: {e}"
        if e.__cause__ is not None:
            line += f" [cause: {type(e.__cause__).__name__}]"
        print(line)

import ast

n = int(input())
total = 0.0

for index in range(n):
    order = ast.literal_eval(input())
    try:
        if not isinstance(order, dict):
            raise TypeError("order must be a dict")
        order_id = order["id"]          # a missing key raises KeyError
        qty = order["qty"]
        price = order["price"]
        if not isinstance(qty, int) or isinstance(qty, bool) or qty <= 0:
            raise ValueError("qty must be a positive int")
        if not isinstance(price, (int, float)) or isinstance(price, bool) or price < 0:
            raise ValueError("price must be a non-negative number")
    except KeyError as err:
        print(f"order {index}: missing {err.args[0]}")
    except (ValueError, TypeError) as err:
        print(f"order {index}: {err}")
    else:
        total += qty * price

print(f"total: {total:.2f}")
